def correct_bracketing(brackets: str) -> bool:
    """
    Returns True if every opening bracket has a corresponding closing bracket.

    :param brackets: A string of "(" and ")"
    :return: A boolean indicating whether the brackets are correctly paired
    """
    stack = []
    for bracket in brackets:
        if bracket == "(":
            stack.append(bracket)
        elif bracket == ")":
            if not stack:
                return False
            stack.pop()
    return not stack

def fibfib(n: int) -> int:
    """The FibFib number sequence is a sequence similar to the Fibonacci sequence 
    that's defined as follows:
    fibfib(0) == 0
    fibfib(1) == 0
    fibfib(2) == 1
    fibfib(n) == fibfib(n-1) + fibfib(n-2) + fibfib(n-3).
    """
    memo = {0: 0, 1: 0, 2: 1}
    def fibfib_helper(k: int) -> int:
        if k not in memo:
            memo[k] = fibfib_helper(k-1) + fibfib_helper(k-2) + fibfib_helper(k-3)
        return memo[k]
    return fibfib_helper(n)

