    """Counts the number of hexadecimal digits that are primes."""
    prime_digits = {'2': 2, '3': 3, '5': 5, '7': 7, 'B': 11, 'D': 13}
    return sum(1 for digit in num if digit in prime_digits and is_prime(prime_digits[digit]))

