def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def count(n, first_digit, last_digit):
        if n == 0:
            return 1 if first_digit == 1 or last_digit == 1 else 0
        else:
            return (10**n - 10**(n-1)) * count(n-1, first_digit, last_digit) if first_digit == 1 else \
                   (10**n - 10**(n-1)) * count(n-1, first_digit, last_digit) if last_digit == 1 else \
                   10**n * count(n-1, first_digit, last_digit) if first_digit == 1 and last_digit == 1 else 0

    return count(n, 1, 1) + count(n, 1, 0) + count(n, 0, 1) + count(n, 0, 0) - 2 * count(n, 1, 1)

